"""Plain-English explanations of financial terms used across the app."""

GLOSSARY: dict[str, dict[str, str]] = {
    "revenue": {"term": "Revenue", "short": "Total money earned from selling goods or services before any costs.",
                "long": "Also called sales or top line. Growth in revenue shows whether demand for the business is rising."},
    "cagr": {"term": "CAGR", "short": "Compound annual growth rate: the steady yearly rate that turns a start value into an end value.",
             "formula": "((End / Start)^(1 / years) − 1) × 100",
             "long": "It smooths out bumpy years. It cannot be calculated when the start or end value is zero or negative (e.g. a loss)."},
    "ebitda": {"term": "EBITDA", "short": "Earnings before interest, tax, depreciation and amortisation: a rough measure of operating cash earnings.",
               "long": "Useful for comparing companies with different debt and asset ages, but it ignores capex and working capital, so it is not cash flow."},
    "ebit": {"term": "EBIT", "short": "Earnings before interest and tax: operating profit after depreciation.",
             "long": "In this app EBIT = profit before tax + interest expense, so it includes other income."},
    "pat": {"term": "PAT / Net profit", "short": "Profit after tax attributable to shareholders: the 'bottom line'."},
    "eps": {"term": "EPS", "short": "Earnings per share: net profit divided by the number of shares.",
            "long": "Diluted EPS assumes options and convertibles become shares. Historical EPS is adjusted for later splits and bonus issues so years are comparable."},
    "roe": {"term": "ROE", "short": "Return on equity: how much profit the company earns on shareholders' money.",
            "formula": "Net profit / Average shareholders' equity × 100",
            "long": "Above ~15% is generally good for Indian companies. High debt can inflate ROE, so read it alongside debt-to-equity."},
    "roce": {"term": "ROCE", "short": "Return on capital employed: profit earned on all long-term capital (equity + debt).",
             "formula": "EBIT / Average (Total assets − Current liabilities) × 100",
             "long": "Unlike ROE, it is not flattered by leverage. Compare it with the cost of capital (~11–13% in India)."},
    "roic": {"term": "ROIC", "short": "Return on invested capital: after-tax operating profit per rupee of capital actually invested in operations.",
             "formula": "EBIT × (1 − tax rate) / Average (Equity + Debt − Cash) × 100"},
    "debt_to_equity": {"term": "Debt-to-equity", "short": "Borrowings divided by shareholders' equity: how much the company relies on debt.",
                       "long": "Normal levels differ by sector: high for utilities and infrastructure, low for software. Not meaningful for banks."},
    "net_debt": {"term": "Net debt", "short": "Total borrowings minus cash and short-term investments. Negative = net cash.",
                 "long": "Gross debt shows total obligations; net debt shows what would remain if cash were used to repay debt."},
    "interest_coverage": {"term": "Interest coverage", "short": "How many times operating profit covers interest payments.",
                          "formula": "EBIT / Interest expense", "long": "Below ~1.5× is a warning sign; above ~5× is comfortable."},
    "current_ratio": {"term": "Current ratio", "short": "Current assets divided by current liabilities: short-term liquidity.",
                      "long": "Below 1 means short-term obligations exceed short-term assets."},
    "fcf": {"term": "Free cash flow (FCF)", "short": "Cash left after running the business and investing in fixed assets.",
            "formula": "Cash flow from operations − Capital expenditure",
            "long": "This is the cash that can pay dividends, reduce debt or fund growth. Indian companies usually report interest paid in financing, so this approximates free cash flow to the firm."},
    "cfo": {"term": "Cash flow from operations (CFO)", "short": "Cash actually generated by the core business in the year.",
            "long": "When CFO is persistently below net profit, reported profits are not turning into cash."},
    "pe": {"term": "P/E ratio", "short": "Price-to-earnings: how many rupees investors pay for each rupee of annual profit.",
           "formula": "Market cap / Net profit (or Price / EPS)",
           "long": "A high P/E implies high expected growth or quality. It is not meaningful when the company makes a loss."},
    "pb": {"term": "P/B ratio", "short": "Price-to-book: market value relative to the accounting value of equity.",
           "long": "The main valuation measure for banks and financial companies."},
    "ev": {"term": "Enterprise value (EV)", "short": "Market cap plus debt minus cash: the value of the whole business, not just equity.",
           "formula": "Market cap + Total debt + Minority interest − Cash & short-term investments"},
    "ev_ebitda": {"term": "EV/EBITDA", "short": "Enterprise value relative to EBITDA. Useful for comparing firms with different debt levels."},
    "peg": {"term": "PEG ratio", "short": "P/E divided by EPS growth rate. Around 1 is often called 'fair' for growth stocks.",
            "long": "Uses past growth here; it is unreliable when growth is low, negative or erratic."},
    "dcf": {"term": "DCF (discounted cash flow)", "short": "Values a business as today's worth of all its future free cash flows.",
            "long": "Extremely sensitive to the discount rate and long-term growth assumptions, so always look at the sensitivity table."},
    "ddm": {"term": "Dividend discount model", "short": "Values a share as today's worth of its future dividends.",
            "formula": "D₁ / (cost of equity − growth)", "long": "Only sensible for steady dividend payers."},
    "dividend_yield": {"term": "Dividend yield", "short": "Annual dividends per share as a % of the share price."},
    "payout_ratio": {"term": "Payout ratio", "short": "Share of net profit paid out as dividends."},
    "nim": {"term": "Net interest margin (NIM)", "short": "A lender's interest income minus interest expense, as a % of earning assets.",
            "long": "This app shows a proxy (NII ÷ average total assets) because interest-earning assets are not in the free data."},
    "gnpa": {"term": "Gross NPA", "short": "Loans on which borrowers have stopped paying for 90+ days, as % of total loans.",
             "long": "A key bank risk measure. It is not available from the free data source; read it in the bank's quarterly results."},
    "car": {"term": "Capital adequacy ratio (CAR)", "short": "A bank's capital relative to its risk-weighted assets; the RBI sets the minimum."},
    "fresh_issue": {"term": "Fresh issue", "short": "New shares created in an IPO. Money goes to the company and existing holders are diluted."},
    "ofs": {"term": "Offer for sale (OFS)", "short": "Existing shareholders sell their shares in the IPO. Money goes to them, not the company."},
    "gmp": {"term": "Grey market premium (GMP)", "short": "An unofficial, unregulated indicator of expected listing price.",
            "long": "Speculative and easily manipulated. It says nothing about long-term business value."},
    "promoter_pledge": {"term": "Promoter pledge", "short": "Promoter shares given as collateral for loans.",
                        "long": "If the price falls, lenders may sell pledged shares, pushing the price down further."},
    "tsr": {"term": "Total shareholder return", "short": "Share-price change plus dividends received, over a period."},
}
